\label{def:piecewise}
A family $G$ is \emph{piecewise constant} if there are
times $0=t_0<t_1<\dots<t_n=T$ and matrices $G_0,\dots,G_{n-1}$ with
$G(t)=G_j$ on each \emph{piece} $(t_j,t_{j+1})$. The $t_j$ are its \emph{piece endpoints}.
Its \emph{induced product} is
\begin{equation}\label{eq:piecewise-product}
  W=e^{-i(t_n-t_{n-1})G_{n-1}}\cdots e^{-i(t_2-t_1)G_1}e^{-i(t_1-t_0)G_0},
\end{equation}
with one unitary per piece, applied in the order of time.

\label{def:sparsity}
A matrix is \emph{$\sigma$-sparse}, for a positive integer $\sigma$, if each row has
at most $\sigma$ nonzero entries.

\label{lem:duhamel}
Let $H,G\colon[a,b]\to\mathbb C^{d\times d}$, let $S\subset[a,b]$ be
countable, and let $U,V\colon[a,b]\to\mathbb C^{d\times d}$ be continuous and
unitary-valued, with $U(a)=V(a)$, such that $i\dotU(t)=H(t)U(t)$ and
$i\dotV(t)=G(t)V(t)$ for every $t\in[a,b]\setminus S$. If
$t\mapsto\|H(t)-G(t)\|$ is integrable, then
\begin{equation}\label{eq:duhamel-integral}
  \|U(b)-V(b)\|\le\int_a^b\|H(t)-G(t)\|\,dt.
\end{equation}

\label{lem:truncation-error}
For nonnegative $k$, if $H$ is $\sigma$-sparse, then
$\|H(t)-H^{(k)}(t)\|\le\sqrt2\,\sigma\,2^{-k}$ for every $t$.

\label{def:midpoint-product}
For nondecreasing checkpoints $0=t_0\le t_1\le\dots\le t_n=T$ and a nonnegative integer
$k$, the \emph{midpoint product} is generated by
the $(k+1)$-bit truncation of each interval's midpoint sample:
\begin{align*}
  W&=e^{-i(t_n-t_{n-1})G_{n-1}}\cdots e^{-i(t_1-t_0)G_0},\\
  G_j&=H\bigl(\tfrac{t_j+t_{j+1}}2\bigr)^{(k+1)},
\end{align*}
where an interval of length zero contributes the identity.

\label{def:jrs-coefficient}
For an integer $m\ge1$ and functions $u,v\ge0$ and $g>0$ on $[0,1]$, the \emph{Jansen--Ruskai--Seiler coefficient} is
\begin{equation}\label{eq:jrs-coefficient}
  J_m(u,v,g)=\frac{m\,u(0)}{g(0)^2}+\frac{m\,u(1)}{g(1)^2}
  +\int_0^1\Bigl(\frac{m\,v}{g^2}+7m\sqrt m\,\frac{u^2}{g^3}\Bigr)\,ds.
\end{equation}

\label{thm:level-evolution}
For a partition $0=a_0<\cdots<a_n=T$, let $V(0)=1$ evolve under constant Hermitian generators
$G_j$ on $(a_j,a_{j+1})$. As in \eqref{eq:piecewise-product}, $V(T)=e^{-i(a_n-a_{n-1})G_{n-1}}\cdots e^{-i(a_1-a_0)G_0}$.
Let $U$ be a unitary-valued function on $[0,T]$ with $U(0)=1$, and let $Y_0,\ldots,Y_{n-1}$ be matrices, with $Y_{-1}=0$.
Define $M_j=U^\dagger(1-iY_j)V$ for $j\in\{-1,0,\ldots,n-1\}$, so $M_{-1}=U^\dagger V$.
If $\|M_j(a_{j+1})-M_j(a_j)\|\le R_j$ for $0\le j<n$, then
\begin{equation}\label{eq:layer-assembly}
 \|V(T)-U(T)\|\le\sum_{j=0}^{n-1}(R_j+\|Y_j-Y_{j-1}\|)+\|Y_{n-1}\|.
\end{equation}

\label{def:unit-product}\label{def:sample-piece}
For integer $T\ge1$, let $H(s)$ be a continuous Hamiltonian on $[0,1]$. Let $U$ evolve under $H(t/T)$ on $[0,T]$. Set
\begin{equation}\label{eq:unit-product}
  W_T=e^{-iH((T-1)/T)}\cdots e^{-iH(0)} .
\end{equation}
The $T$ factors are ordered by decreasing sample index.
The piece for sample $H(j/T)$ is $[j-\tfrac12,j+\tfrac12]\cap[0,T]$, a full unit interval for $0<j<T$ and a half interval for $j=0,T$.
The \emph{rounded clock} is $q(t)=\lfloor t+1/2\rfloor$ for $t\ge0$.

\label{def:unit-coefficients}
For the unit-step comparison, using the frame-operator bounds $N_\gamma$ and $N'_\gamma$ of \Cref{lem:bernoulli-inverse}, define
\begin{equation}\label{eq:unit-coefficients}
 c_0=\tfrac14+2N_\gamma,\qquad
 c_1=\tfrac1{64}+\tfrac14N_\gamma+N'_\gamma,\qquad
 c_2=\tfrac1{12}+2N_\gamma.
\end{equation}
At width $w<2\pi$, write $c_i(w)$ for the explicit values obtained by replacing $N_\gamma,N'_\gamma$ with $\mathcal N(w),2\mathcal N'(w)$.

\label{lem:qlsp-walk-circuit}
Let $O$, $V$, $A$, and $b$ be as in \Cref{cor:qlsp-walk}, and use the walk construction of \Cref{def:qlsp-walk-construction}. Write $E_{1,0},E_{0,1}$ for $E$ with $R$ replaced by $R_{1,0},R_{0,1}$, respectively. Then, for every real
$f$ and, along the schedule, every $s$ at which $s\mapsto f(s)$ is twice differentiable:
\begin{enumerate}
\item $E$ is a Hermitian involution and $L^\dagger EL=H(f)/(2\sqrt2\,\alpha(f))$.
\item $E=((1-f)E_{1,0}+fE_{0,1})/\alpha$ with $E_{1,0}$ and $E_{0,1}$ Hermitian involutions,
and, with $\alpha=\alpha(f(s))$, $\|W'(s)\|\le|f'(s)|/\alpha^2$ and
$\|W''(s)\|\le(|f''(s)|+\tfrac4{\sqrt3}|f'(s)|^2)/\alpha^2$.
\item $ZL=L\operatorname{diag}(I,Q_b)$, and $Z$ commutes with $E$ and with $W(s)$.
\end{enumerate}
